import { Melody } from 'app/services/MelodiesService/types';
import { getNote, pitchNote } from 'app/services/NotesService';
import { Note } from 'app/services/NotesService/types';
import { SettingsState } from 'app/services/SettingsService/slice/types';

import { noteColors } from 'styles/theme/noteColors';

// Judgement windows are in real milliseconds, independent of playback speed.
// Both endpoints are included. A note becomes a miss strictly after the window.
export const HIT_WINDOW = 300;
export const TIMING_TOLERANCES = [180, 300, 450];
export const PERFECT_WINDOW = 70;
export const LEAD_IN = 3000;
export const LOOK_AHEAD = 3000;
export type PracticeMode = 'rhythm' | 'wait';

export type Grade = 'perfect' | 'good' | 'miss';
export type Session = {
  results: (Grade | null)[];
  score: number;
  combo: number;
  bestCombo: number;
  wrongNotes: number;
  feedback: { text: string; at: number } | null;
};

export const createSession = (noteCount: number): Session => ({
  results: Array(noteCount).fill(null),
  score: 0,
  combo: 0,
  bestCombo: 0,
  wrongNotes: 0,
  feedback: null,
});

// Chords have exactly the same recorded start. Nearby attacks remain separate.
export const getNextTargets = (session: Session, notes: Melody['notes']) => {
  let start = Infinity;
  notes.forEach((note, i) => {
    if (session.results[i] === null) start = Math.min(start, note.start);
  });
  return notes.flatMap((note, i) =>
    session.results[i] === null && note.start === start ? [i] : [],
  );
};

export const getNextVisualTargets = (
  session: Session,
  notes: Melody['notes'],
  elapsed: number,
  listening: boolean,
) => {
  if (!listening) return getNextTargets(session, notes);
  // Reference playback never resolves scores, so follow its upcoming onsets.
  let start = Infinity;
  notes.forEach(note => {
    if (note.start >= elapsed) start = Math.min(start, note.start);
  });
  return notes.flatMap((note, i) => (note.start === start ? [i] : []));
};

export const judgeWaitingNote = (
  session: Session,
  notes: Melody['notes'],
  note: Note,
  time: number,
  speed: number,
  hitWindow = HIT_WINDOW,
): Session => {
  const targets = getNextTargets(session, notes);
  const index = targets.find(i => notes[i].note === note);
  // Accept the next group up to one normal hit window early, and indefinitely
  // at its onset. A different pitch cannot unlock a later group.
  if (index === undefined || time < notes[index].start - hitWindow * speed) {
    return {
      ...session,
      combo: 0,
      wrongNotes: session.wrongNotes + 1,
      feedback: { text: 'Другая клавиша', at: time },
    };
  }
  const combo = session.combo + 1;
  return {
    ...session,
    results: session.results.map((result, i) =>
      i === index ? 'perfect' : result,
    ),
    score: session.score + 100,
    combo,
    bestCombo: Math.max(session.bestCombo, combo),
    feedback: { text: 'Верно', at: time },
  };
};

export const advanceSession = (
  session: Session,
  notes: Melody['notes'],
  time: number,
  speed: number,
  hitWindow = HIT_WINDOW,
): Session => {
  const missed = notes.some(
    (note, i) =>
      session.results[i] === null && time - note.start > hitWindow * speed,
  );
  if (!missed) return session;
  return {
    ...session,
    results: session.results.map((result, i) =>
      result === null && time - notes[i].start > hitWindow * speed
        ? 'miss'
        : result,
    ),
    combo: 0,
    feedback: { text: 'Пропуск', at: time },
  };
};

export const judgeNote = (
  session: Session,
  notes: Melody['notes'],
  note: Note,
  time: number,
  speed: number,
  hitWindow = HIT_WINDOW,
): Session => {
  const current = advanceSession(session, notes, time, speed, hitWindow);
  let closest = -1;
  let distance = Infinity;
  notes.forEach((target, i) => {
    const delta = Math.abs(target.start - time);
    if (
      target.note === note &&
      current.results[i] === null &&
      delta <= hitWindow * speed &&
      delta < distance
    ) {
      closest = i;
      distance = delta;
    }
  });

  if (closest === -1) {
    return {
      ...current,
      combo: 0,
      wrongNotes: current.wrongNotes + 1,
      feedback: { text: 'Мимо', at: time },
    };
  }

  const grade: Grade = distance <= PERFECT_WINDOW * speed ? 'perfect' : 'good';
  const combo = current.combo + 1;
  return {
    ...current,
    results: current.results.map((result, i) =>
      i === closest ? grade : result,
    ),
    score: current.score + (grade === 'perfect' ? 100 : 70),
    combo,
    bestCombo: Math.max(current.bestCombo, combo),
    feedback: { text: grade === 'perfect' ? 'Точно!' : 'Хорошо', at: time },
  };
};

export const getSessionStats = (session: Session) => {
  const perfect = session.results.filter(result => result === 'perfect').length;
  const good = session.results.filter(result => result === 'good').length;
  const missed = session.results.filter(result => result === 'miss').length;
  const attempts = perfect + good + missed + session.wrongNotes;
  return {
    perfect,
    good,
    missed,
    hits: perfect + good,
    accuracy: attempts ? Math.round(((perfect + good) / attempts) * 100) : null,
  };
};

const CHROMATIC = [
  'C',
  'C#',
  'D',
  'D#',
  'E',
  'F',
  'F#',
  'G',
  'G#',
  'A',
  'A#',
  'B',
];
const noteNumber = (note: Note) =>
  Number(note.slice(-1)) * 12 + CHROMATIC.indexOf(note.slice(0, -1));

export const getPianoLanes = (notes: Melody['notes']) => {
  if (!notes.length) return [];
  const numbers = notes.map(({ note }) => noteNumber(note));
  const first = Math.floor(Math.min(...numbers) / 12) * 12;
  const last = Math.floor(Math.max(...numbers) / 12) * 12 + 11;
  const whiteCount = ((last - first + 1) / 12) * 7;
  let whiteIndex = 0;
  return Array.from({ length: last - first + 1 }, (_, i) => {
    const number = first + i;
    const name = CHROMATIC[number % 12];
    const sharp = name.includes('#');
    const left = ((whiteIndex - (sharp ? 0.31 : 0)) / whiteCount) * 100;
    if (!sharp) whiteIndex++;
    return {
      note: `${name}${Math.floor(number / 12)}` as Note,
      sharp,
      left,
      width: ((sharp ? 0.62 : 1) / whiteCount) * 100,
      color:
        number < (first + last) / 2
          ? noteColors.pianoLow
          : noteColors.pianoHigh,
    };
  });
};

export const getNoteBindings = ({
  applicature,
  scaleNotes,
  octave,
  pitch,
}: Pick<SettingsState, 'applicature' | 'scaleNotes' | 'octave' | 'pitch'>) => {
  const bindings = new Map<Note, typeof applicature[number]>();
  applicature.forEach((key, i) => {
    const note = pitchNote(
      getNote(
        scaleNotes[i % scaleNotes.length],
        (octave + Math.floor(i / scaleNotes.length)) as typeof octave,
      ),
      pitch,
    );
    bindings.set(note, key);
  });
  return bindings;
};
