import { createPortal } from 'react-dom';
import styled from 'styled-components';

import type { RecordingMode } from 'app/services/GuitarInputService/liveTranscription';
import { useGuitarInput } from 'app/services/GuitarInputService/useGuitarInput';

import { LiveAudioRecognition } from './LiveAudioRecognition';
import { LiveInputEffects } from './LiveInputEffects';
import { NoiseGateControls } from './NoiseGateControls';

export const GuitarInput = ({
  open,
  guitar,
}: {
  open: boolean;
  guitar: ReturnType<typeof useGuitarInput>;
}) => {
  const db = Math.max(
    -60,
    Math.round(20 * Math.log10(guitar.level.rms || 0.001)),
  );
  return (
    <Wrapper>
      {guitar.monitoring &&
        createPortal(
          <EmergencyMute
            type="button"
            onClick={guitar.stopMonitoring}
            aria-label="Мгновенно выключить живой звук"
          >
            Выключить звук
          </EmergencyMute>,
          document.body,
        )}
      {open && (
        <Panel aria-label="Микрофон и гитара">
          <p>
            Выберите микрофон или вход аудиоинтерфейса и разрешите доступ.
            Гитара подключается через инструментальный вход Hi-Z.
          </p>
          <p>
            Подключение и включённость живого звука запоминаются и
            восстанавливаются после перезагрузки. При первом подключении звук
            включается автоматически. Если браузер требует разрешение или
            нажатие, подтвердите доступ и повторите подключение. Микрофон рядом
            с динамиками может вызвать свист.
          </p>
          {guitar.connecting && <p role="status">{guitar.connectionStatus}</p>}
          <NoiseGateControls
            settings={guitar.noiseGate}
            onChange={guitar.updateNoiseGate}
          />
          {!guitar.supported ? (
            <p role="status">
              Аудиозахват недоступен. Откройте Qwertophone через HTTPS или
              localhost в браузере с Web Audio и AudioWorklet.
            </p>
          ) : guitar.connected ? (
            <>
              <Fields>
                <label>
                  Аудиоустройство
                  <select
                    aria-label="Устройство аудиовхода"
                    value={guitar.deviceId}
                    disabled={guitar.isRecording}
                    onChange={event => guitar.selectDevice(event.target.value)}
                  >
                    {!guitar.devices.some(
                      device => device.deviceId === guitar.deviceId,
                    ) && (
                      <option value={guitar.deviceId}>Текущий аудиовход</option>
                    )}
                    {guitar.devices.map((device, index) => (
                      <option key={device.deviceId} value={device.deviceId}>
                        {device.label || `Аудиовход ${index + 1}`}
                      </option>
                    ))}
                  </select>
                </label>
                <label>
                  Канал аудиоинтерфейса
                  <select
                    aria-label="Канал аудиовхода"
                    value={guitar.channel}
                    disabled={guitar.isRecording}
                    onChange={event =>
                      guitar.selectChannel(Number(event.target.value))
                    }
                  >
                    {Array.from({ length: guitar.channels }, (_, channel) => (
                      <option key={channel} value={channel}>
                        Вход {channel + 1}
                      </option>
                    ))}
                  </select>
                </label>
              </Fields>
              {guitar.canSelectOutput ? (
                <label>
                  Аудиовыход
                  <select
                    aria-label="Аудиовыход живого звука"
                    value={guitar.outputDeviceId}
                    onChange={event => guitar.selectOutput(event.target.value)}
                  >
                    <option value="">Системный выход</option>
                    {guitar.outputs
                      .filter(output => output.deviceId !== 'default')
                      .map((output, index) => (
                        <option key={output.deviceId} value={output.deviceId}>
                          {output.label || `Выход ${index + 1}`}
                        </option>
                      ))}
                  </select>
                </label>
              ) : (
                <p>Аудиовыход выбирается в настройках системы или браузера.</p>
              )}
              <Level>
                <span>Уровень входа: {db} dBFS</span>
                <meter
                  min={-60}
                  max={0}
                  value={db}
                  aria-label="Уровень входного звука"
                />
                {guitar.level.peak >= 0.98 ? (
                  <span role="status">
                    Перегруз. Уменьшите усиление аудиоинтерфейса.
                  </span>
                ) : (
                  <span>Если сигнала нет, проверьте канал и усиление.</span>
                )}
              </Level>
              <Actions>
                {guitar.monitoring ? (
                  <Mute type="button" onClick={guitar.stopMonitoring}>
                    Выключить живой звук
                  </Mute>
                ) : (
                  <button type="button" onClick={guitar.startMonitoring}>
                    Включить живой звук
                  </button>
                )}
                <span role="status">
                  {guitar.monitoring ? 'Звук включён' : 'Вывод звука выключен'}
                </span>
              </Actions>
              {guitar.monitoring && (
                <Level>
                  <span>Уровень выхода</span>
                  <meter
                    aria-label="Уровень живого выхода"
                    min={-60}
                    max={0}
                    value={Math.max(
                      -60,
                      20 * Math.log10(guitar.outputLevel.rms || 0.001),
                    )}
                  />
                  {guitar.outputLevel.peak >= 0.98 && (
                    <span role="status">
                      Перегруз выхода. Уменьшите громкость или драйв.
                    </span>
                  )}
                </Level>
              )}
              <LiveInputEffects
                settings={guitar.liveEffects}
                onChange={guitar.updateLiveEffects}
              />
              {guitar.latency && (
                <details>
                  <summary>Задержка и аудиоустройство</summary>
                  <p>
                    Частота: {guitar.latency.sampleRate} Гц. Блок:{' '}
                    {guitar.latency.quantumFrames} кадров,{' '}
                    {(
                      (guitar.latency.quantumFrames /
                        guitar.latency.sampleRate) *
                      1000
                    ).toFixed(2)}{' '}
                    мс
                    {guitar.latency.quantumReported ? '' : ' (запрошен)'}.
                  </p>
                  <p>
                    Ввод: {latencyLabel(guitar.latency.inputMs)}. Буфер выхода:{' '}
                    {latencyLabel(guitar.latency.baseMs)}. Устройство вывода:{' '}
                    {latencyLabel(guitar.latency.outputMs)}.
                  </p>
                  <p>
                    Это показатели браузера. Полная задержка от микрофона до
                    наушников требует отдельного измерения. Для минимальной
                    задержки используйте проводное подключение.
                  </p>
                </details>
              )}
              <p>
                Запись сохраняет входной сигнал до эффектов. Выберите, когда
                распознавать ноты.
              </p>
              <label>
                Распознавание аудио
                <select
                  aria-label="Режим распознавания аудио"
                  value={guitar.recordingMode}
                  disabled={guitar.isRecording || guitar.processing}
                  onChange={event =>
                    guitar.setRecordingMode(event.target.value as RecordingMode)
                  }
                >
                  <option value="live">
                    Ноты и аккорды в реальном времени
                  </option>
                  <option value="live-mono">Одна нота: быстрый режим</option>
                  <option value="polyphonic">
                    Ноты и аккорды после записи
                  </option>
                </select>
              </label>
              <p>
                {guitar.recordingMode === 'live'
                  ? 'Играйте ноты и аккорды: до восьми голосов появляются на нотном стане и табулатуре во время записи. Короткое окно анализа помогает отделить ноты от обертонов. Используйте чистый сигнал одного инструмента. Живой звук можно оставить включённым.'
                  : guitar.recordingMode === 'live-mono'
                  ? 'Играйте по одной ноте. Быстрый одноголосный режим подходит для коротких звуков и быстрых пассажей.'
                  : 'Ноты и полные аккорды распознаются после остановки записи и выключения живого звука.'}
              </p>
              {guitar.isRecording && guitar.recordingMode !== 'polyphonic' && (
                <p role="status">
                  Ноты записываются в реальном времени. Закройте подключения,
                  чтобы видеть нотный стан или табулатуру.
                </p>
              )}
              <LiveAudioRecognition />
              <Actions>
                <button
                  type="button"
                  disabled={guitar.processing && !guitar.isRecording}
                  onClick={guitar.toggleRecording}
                >
                  {guitar.isRecording
                    ? guitar.recordingMode !== 'polyphonic'
                      ? 'Остановить аудиозапись'
                      : 'Остановить и распознать'
                    : 'Записать аудио'}
                </button>
                <button type="button" onClick={guitar.disconnect}>
                  Отключить вход
                </button>
              </Actions>
              <p>
                Можно также использовать запись в песочнице. Если слушаете
                обработанный звук в Qwertophone, выключите Direct Monitor на
                аудиоинтерфейсе, чтобы не слышать второй, чистый сигнал.
              </p>
            </>
          ) : (
            <Actions>
              <button
                type="button"
                disabled={guitar.connecting}
                onClick={() => guitar.connect()}
              >
                {guitar.connecting ? 'Подключение…' : 'Подключить аудиовход'}
              </button>
              {guitar.connecting && (
                <button type="button" onClick={guitar.disconnect}>
                  Отменить
                </button>
              )}
            </Actions>
          )}
          {guitar.processing && (
            <div role="status">
              <p>
                {guitar.progress > 0
                  ? `Распознавание: ${Math.round(guitar.progress * 100)}%`
                  : 'Загрузка распознавания…'}
              </p>
              <progress
                max={1}
                value={guitar.progress || undefined}
                aria-label="Распознавание гитары"
              />
            </div>
          )}
          {guitar.error && <p role="alert">{guitar.error}</p>}
          {guitar.exportError && <p role="alert">{guitar.exportError}</p>}
          {guitar.notice && <p role="status">{guitar.notice}</p>}
          {guitar.hasTake && (
            <>
              <p>
                Скачайте последний аудиодубль без обработки или с текущими
                эффектами входа, громкостью и шумоподавлением. Эффекты можно
                менять после записи и скачивать новые варианты. Чистый звук
                сохраняется неизменным.
              </p>
              {!guitar.connected && (
                <LiveInputEffects
                  settings={guitar.liveEffects}
                  onChange={guitar.updateLiveEffects}
                />
              )}
              <Actions>
                <button type="button" onClick={guitar.download}>
                  Скачать чистый WAV
                </button>
                <button
                  type="button"
                  disabled={guitar.exporting}
                  onClick={guitar.downloadWithEffects}
                >
                  {guitar.exporting
                    ? 'Обработка эффектов…'
                    : 'Скачать WAV с эффектами'}
                </button>
                {guitar.error && guitar.canRetry && (
                  <button
                    type="button"
                    disabled={guitar.processing}
                    onClick={guitar.retry}
                  >
                    Повторить распознавание
                  </button>
                )}
              </Actions>
              {guitar.exporting && (
                <p role="status">Готовим WAV с текущими эффектами…</p>
              )}
            </>
          )}
        </Panel>
      )}
    </Wrapper>
  );
};

const Wrapper = styled.div`
  display: contents;
  button,
  select {
    font-size: 12px;
  }
`;
const Mute = styled.button`
  order: 2;
  min-height: 42px;
  border-color: ${p => p.theme.primary};
  color: ${p => p.theme.primary};
`;
const EmergencyMute = styled(Mute)`
  position: fixed;
  right: 16px;
  bottom: 16px;
  z-index: 2000;
  background: ${p => p.theme.surface};
  border: 2px solid ${p => p.theme.primary};
  border-radius: 8px;
  padding: 10px 16px;
  box-shadow: 0 2px 12px ${p => p.theme.shadow};
`;

const latencyLabel = (value?: number) =>
  value === undefined ? 'нет данных' : `${value.toFixed(2)} мс`;
const Panel = styled.section`
  min-width: 0;
  font-size: 12px;
  p {
    margin: 12px 0;
    line-height: 1.5;
    color: ${p => p.theme.textSecondary};
  }
  label {
    display: flex;
    flex: 1;
    min-width: 0;
    flex-direction: column;
    gap: 6px;
  }
  select,
  progress,
  meter {
    width: 100%;
  }
`;
const Fields = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  label {
    min-width: min(210px, 100%);
  }
`;
const Actions = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
`;
const Level = styled.div`
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 12px;
  color: ${p => p.theme.textSecondary};
`;
