import { useTheme } from 'styled-components';

// A decorative image: the adjacent wordmark supplies the accessible name.
export const BrandLogo = () => {
  const theme = useTheme();
  return (
    <img
      src={`${process.env.PUBLIC_URL || ''}/brand/logo-${theme.key}-192.webp`}
      width="40"
      height="40"
      alt=""
      aria-hidden="true"
    />
  );
};
