import { getTimeSignature } from '../MelodiesService/meter';
import { DEFAULT_BPM } from '../MelodiesService/timing';
import type { Melody } from '../MelodiesService/types';
import { MelodyExportError } from './errors';
import { getExportNotes } from './notes';

const PPQ = 960;
const variableLength = (value: number): number[] => {
  if (!Number.isSafeInteger(value) || value < 0 || value > 0x0fffffff) {
    throw new MelodyExportError('Мелодия слишком длинная для MIDI-файла.');
  }
  const bytes = [value & 0x7f];
  while ((value = Math.floor(value / 128)))
    bytes.unshift((value & 0x7f) | 0x80);
  return bytes;
};

const programFor = (timbre: string) => {
  const name = timbre.toLowerCase();
  if (/distort|tele/.test(name)) return 30;
  if (/guitar|acclassy|acousticsteel|ac12|acdark|acclean/.test(name)) return 25;
  if (/bass/.test(name)) return 33;
  if (/accordion/.test(name)) return 21;
  if (/organ/.test(name)) return 19;
  if (/cello/.test(name)) return 42;
  if (/strings/.test(name)) return 48;
  if (/horn/.test(name)) return 60;
  if (/harpsichord/.test(name)) return 6;
  if (/celeste/.test(name)) return 8;
  if (/electric|epiano/.test(name)) return 4;
  if (/8bit|sine|sawtooth|square|triangle/.test(name)) return 80;
  return 0;
};

export const encodeMidi = (melody: Melody): Uint8Array => {
  const notes = getExportNotes(melody);
  const bpm =
    Number.isFinite(melody.bpm) && melody.bpm! > 0 ? melody.bpm! : DEFAULT_BPM;
  const tempo = Math.max(1, Math.min(0xffffff, Math.round(60000000 / bpm)));
  const ticks = (ms: number) => Math.round((ms * 1000 * PPQ) / tempo);
  const [numerator, denominator] = getTimeSignature(melody.timeSignature)
    .split('/')
    .map(Number);
  const channel = melody.timbre === 'drums' ? 9 : 0;
  const title = new TextEncoder().encode(melody.title || 'Запись');
  const track: number[] = [
    0,
    0xff,
    0x03,
    ...variableLength(title.length),
    ...Array.from(title),
    0,
    0xff,
    0x51,
    3,
    (tempo >> 16) & 255,
    (tempo >> 8) & 255,
    tempo & 255,
    0,
    0xff,
    0x58,
    4,
    numerator,
    Math.log2(denominator),
    24,
    8,
    0,
    0xc0 | channel,
    programFor(melody.timbre),
  ];
  const events = notes
    .flatMap(note => {
      const pitch = note.pitch - (channel === 9 ? 12 : 0);
      const start = ticks(note.start);
      return [
        { tick: start, on: true, pitch },
        { tick: Math.max(start + 1, ticks(note.end)), on: false, pitch },
      ];
    })
    .sort(
      (a, b) =>
        a.tick - b.tick || Number(a.on) - Number(b.on) || a.pitch - b.pitch,
    );
  let previousTick = 0;
  events.forEach(({ tick, on, pitch }) => {
    track.push(
      ...variableLength(tick - previousTick),
      (on ? 0x90 : 0x80) | channel,
      pitch,
      on ? 100 : 0,
    );
    previousTick = tick;
  });
  track.push(0, 0xff, 0x2f, 0);
  const file = new Uint8Array(22 + track.length);
  file.set([
    0x4d,
    0x54,
    0x68,
    0x64,
    0,
    0,
    0,
    6,
    0,
    0,
    0,
    1,
    PPQ >> 8,
    PPQ & 255,
  ]);
  file.set([0x4d, 0x54, 0x72, 0x6b], 14);
  new DataView(file.buffer).setUint32(18, track.length);
  file.set(track, 22);
  return file;
};
