export interface EffectStage {
  equalizer: { enabled: boolean; low: number; mid: number; high: number };
  distortion: { enabled: boolean; drive: number; tone: number };
  compressor: { enabled: boolean; threshold: number; ratio: number };
  chorus: { enabled: boolean; rate: number; depth: number; mix: number };
  delay: { enabled: boolean; time: number; feedback: number; mix: number };
  reverb: { enabled: boolean; mix: number; tone: number };
}

export interface PresetPedal {
  id: string;
  presetId: string;
  name: string;
  enabled: boolean;
  stages: EffectStage[];
}

export interface InstrumentEffects extends EffectStage {
  bypass: boolean;
  volume: number;
  pedals?: PresetPedal[];
}

export const MAX_PEDALS = 12;
export const MAX_PEDAL_STAGES = 24;
export type EffectName = keyof EffectStage;
export type EffectsByTimbre = Record<string, InstrumentEffects>;

export const LIVE_INPUT_EFFECTS_KEY = 'live-audio-input';

export const maxEffectsVolume = (timbre: string) =>
  timbre === LIVE_INPUT_EFFECTS_KEY ? 300 : 100;

