export const effectNames = Object.keys(effectDefinitions) as EffectName[];

export const defaultEffects = (timbre: string): InstrumentEffects => ({
  bypass: false,
  volume:
    timbre === 'distortedGuitar'
      ? 20
      : timbre === LIVE_INPUT_EFFECTS_KEY
      ? 30
      : 100,
  equalizer: { enabled: false, low: 0, mid: 0, high: 0 },
  distortion: {
    enabled: timbre === 'distortedGuitar' || timbre === LIVE_INPUT_EFFECTS_KEY,
    drive: timbre === LIVE_INPUT_EFFECTS_KEY ? 35 : 80,
    tone: 3500,
  },
  compressor: { enabled: false, threshold: -24, ratio: 4 },
  chorus: { enabled: false, rate: 0.8, depth: 3, mix: 35 },
  delay: { enabled: false, time: 300, feedback: 35, mix: 25 },
  reverb: { enabled: false, mix: 25, tone: 6000 },
});

const record = (value: unknown): Record<string, unknown> =>
  value !== null && typeof value === 'object' && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};

const numberInRange = (
  value: unknown,
  fallback: number,
  min: number,
  max: number,
) =>
  typeof value === 'number' && Number.isFinite(value)
    ? Math.min(max, Math.max(min, value))
    : fallback;

const normalizeSingleEffects = (
  timbre: string,
  value: unknown,
): InstrumentEffects => {
  const result = defaultEffects(timbre);
  const saved = record(value);
  result.bypass =
    typeof saved.bypass === 'boolean' ? saved.bypass : result.bypass;
  result.volume = numberInRange(
    saved.volume,
    result.volume,
    0,
    maxEffectsVolume(timbre),
  );
  effectNames.forEach(name => {
    const effect = record(saved[name]);
    const target = result[name] as unknown as Record<string, number | boolean>;
    if (typeof effect.enabled === 'boolean') target.enabled = effect.enabled;
    effectDefinitions[name].controls.forEach(({ key, min, max }) => {
      target[key] = numberInRange(effect[key], target[key] as number, min, max);
    });
  });
  return result;
};

export const toEffectStage = (value: InstrumentEffects): EffectStage =>
  Object.fromEntries(
    effectNames.map(name => [name, { ...value[name] }]),
  ) as unknown as EffectStage;

export const normalizeEffects = (
  timbre: string,
  value: unknown,
): InstrumentEffects => {
  const result = normalizeSingleEffects(timbre, value);
  const saved = record(value);
  if (!Array.isArray(saved.pedals)) return result;
  const pedals: PresetPedal[] = [];
  let stageCount = 0;
  for (const item of saved.pedals.slice(0, MAX_PEDALS)) {
    const pedal = record(item);
    if (
      typeof pedal.id !== 'string' ||
      !pedal.id ||
      typeof pedal.presetId !== 'string' ||
      !pedal.presetId ||
      typeof pedal.name !== 'string' ||
      !pedal.name.trim() ||
      !Array.isArray(pedal.stages) ||
      pedals.some(other => other.id === pedal.id)
    )
      continue;
    const stages = pedal.stages
      .slice(0, MAX_PEDAL_STAGES - stageCount)
      .filter(
        stage => stage && typeof stage === 'object' && !Array.isArray(stage),
      )
      .map(stage => toEffectStage(normalizeSingleEffects('', stage)));
    if (!stages.length) continue;
    pedals.push({
      id: pedal.id,
      presetId: pedal.presetId,
      name: pedal.name.trim().slice(0, 60),
      enabled: pedal.enabled !== false,
      stages,
    });
    stageCount += stages.length;
  }
  result.pedals = pedals;
  return result;
};

export const EFFECTS_STORAGE_KEY = 'qwertophone.instrument-effects.v1';

export const loadEffects = (): EffectsByTimbre => {
  try {
    const saved = record(
      JSON.parse(
        localStorage.getItem(EFFECTS_STORAGE_KEY) ??
          localStorage.getItem('quartet.instrument-effects.v1') ??
          'null',
      ),
    );
    if (saved.version !== 1) return {};
    return Object.fromEntries(
      Object.entries(record(saved.instruments)).map(([timbre, settings]) => [
        timbre,
        normalizeEffects(timbre, settings),
      ]),
    );
  } catch {
    return {};
  }
};

export const saveEffects = (instruments: EffectsByTimbre) => {
  try {
    localStorage.setItem(
      EFFECTS_STORAGE_KEY,
      JSON.stringify({ version: 1, instruments }),
    );
  } catch {
    // Keep the live session usable when storage is blocked or full.
  }
};
